  push('CREDIT', 'READY', 77, 'CDX credit stress 확인', 'CDX', 'risk/liquidity/vol spread proxy');
  push('FUTURES', 'READY', 76, 'FUTX futures board 확인', 'FUTX', 'index/vol/crypto/energy contracts');
  push('FX', 'READY', 75, 'FXX FX matrix 확인', 'FXX', 'USD/risk FX/crypto proxy');
