def utc_now() -> str:
    return datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")


def read_json(path: Path) -> tuple[Any | None, str | None]:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig")), None
    except FileNotFoundError:
        return None, f"missing: {path}"
    except Exception as exc:  # noqa: BLE001 - expose local read errors to UI
        return None, f"failed to read {path}: {exc}"


def read_text(path: Path) -> tuple[str, str | None]:
    try:
        return path.read_text(encoding="utf-8-sig"), None
    except UnicodeDecodeError:
        try:
            return path.read_text(encoding="utf-8", errors="replace"), None
        except Exception as exc:  # noqa: BLE001
            return "", f"failed to read {path}: {exc}"
    except FileNotFoundError:
        return "", f"missing: {path}"
    except Exception as exc:  # noqa: BLE001
        return "", f"failed to read {path}: {exc}"


def is_sensitive_key(key: str) -> bool:
    key_l = key.lower()
    return any(word in key_l for word in SENSITIVE_KEYWORDS)


def sanitize(value: Any, key: str = "") -> Any:
    if is_sensitive_key(key):
        return "<redacted>"
    if isinstance(value, dict):
        return {k: sanitize(v, k) for k, v in value.items()}
    if isinstance(value, list):
        return [sanitize(item, key) for item in value]
    return value


def size_human(size: int) -> str:
    if size < 1024:
        return f"{size} B"
    if size < 1024 * 1024:
        return f"{size / 1024:.1f} KB"
    return f"{size / (1024 * 1024):.1f} MB"


def find_job(jobs_data: Any, job_id: str) -> dict[str, Any]:
    if isinstance(jobs_data, dict):
        if isinstance(jobs_data.get("jobs"), list):
            jobs = jobs_data["jobs"]
        elif job_id in jobs_data and isinstance(jobs_data[job_id], dict):
            job = jobs_data[job_id].copy()
            job.setdefault("id", job_id)
            return job
        else:
            jobs = [jobs_data]
    elif isinstance(jobs_data, list):
        jobs = jobs_data
    else:
        jobs = []

    for item in jobs:
        if not isinstance(item, dict):
            continue
        if str(item.get("id") or item.get("job_id") or "") == job_id:
            return item.copy()
        if "US stock sector/theme" in str(item.get("name") or ""):
            return item.copy()
    return {}


def compact_job(job: dict[str, Any]) -> dict[str, Any]:
    keys = [
        "id",
        "job_id",
        "name",
        "enabled",
        "state",
        "last_status",
        "last_run_at",
        "next_run_at",
        "last_delivery_error",
        "schedule",
        "repeat",
    ]
    return {k: sanitize(job.get(k), k) for k in keys if k in job}


def compact_watchdog(state: Any) -> dict[str, Any]:
    if not isinstance(state, dict):
        return {}
    targets = state.get("targets") if isinstance(state.get("targets"), dict) else {}
    target = targets.get("us_sector") or targets.get("sector") or {}
    if not isinstance(target, dict):
        target = {}
    compact = sanitize(target)
    if isinstance(compact, dict):
        return compact
    return {}


def strip_cron_envelope(lines: list[str]) -> list[str]:
    while lines and not lines[0].strip():
        lines.pop(0)
    if lines and lines[0].startswith("# Cron Job:"):
        lines.pop(0)
        while lines and not lines[0].startswith("---"):
            lines.pop(0)
        if lines and lines[0].startswith("---"):
            lines.pop(0)
    while lines and not lines[0].strip():
        lines.pop(0)
    return lines


def parse_sections(text: str) -> list[dict[str, str]]:
    cleaned = text.strip("\ufeff\n ")
    if not cleaned:
        return []

    # Drop the Hermes cron envelope from output files; keep the Telegram body.
    lines = strip_cron_envelope([line.rstrip() for line in cleaned.splitlines()])

    sections: list[dict[str, str]] = []
    current_title = "요약"
    current_lines: list[str] = []

    def flush() -> None:
        nonlocal current_lines, current_title
        body = "\n".join(line for line in current_lines).strip()
        if body or current_title != "요약":
            sections.append({"title": current_title, "body": body})
        current_lines = []

    for line in lines:
        match = re.match(r"^\s*(\d+)\)\s*(.+?)\s*$", line)
        if match:
            flush()
            current_title = f"{match.group(1)}) {match.group(2)}"
        else:
            current_lines.append(line)
    flush()
    return sections


def clean_output_text(text: str) -> str:
    lines = strip_cron_envelope([line.rstrip() for line in text.strip("\ufeff\n ").splitlines()])
    return "\n".join(lines).strip()


def preview_text(text: str, limit: int = 160) -> str:
    body = clean_output_text(text)
    body = re.sub(r"\s+", " ", body).strip()
    return body[:limit] + ("…" if len(body) > limit else "")


def display_time_from_name(stem: str) -> str:
    try:
        return datetime.strptime(stem, "%Y-%m-%d_%H-%M-%S").strftime("%Y-%m-%d %H:%M:%S")
    except ValueError:
        return stem.replace("_", " ")

def load_theme_baskets() -> dict[str, Any]:
    config_path = Path(__file__).resolve().parents[1] / "src" / "us" / "sector" / "theme_config.py"
    if not config_path.exists():
        return {"theme_baskets": [], "sub_theme_baskets": []}
    try:
        tree = ast.parse(config_path.read_text(encoding="utf-8"))
    except Exception:
        return {"theme_baskets": [], "sub_theme_baskets": []}

    values: dict[str, Any] = {}
    for node in tree.body:
        target_name: str | None = None
        value_node: ast.AST | None = None
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            target_name = node.target.id
            value_node = node.value
        elif isinstance(node, ast.Assign) and node.targets and isinstance(node.targets[0], ast.Name):
            target_name = node.targets[0].id
            value_node = node.value
        if target_name in {"USER_THEME_BASKETS", "USER_SUB_THEME_BASKETS"} and value_node is not None:
            try:
                values[target_name] = ast.literal_eval(value_node)
            except Exception:
                values[target_name] = {}

    def compact(items: dict[str, Any]) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for key, item in items.items():
            if not isinstance(item, dict):
                continue
            out.append(
                {
                    "key": key,
                    "name": item.get("name") or key,
                    "parent": item.get("parent"),
                    "symbols": list(item.get("symbols") or ()),
                    "anchor_symbols": list(item.get("anchor_symbols") or ()),
                    "excluded_from_score": list(item.get("excluded_from_score") or ()),
                }
            )
        return out

    return {
        "theme_baskets": compact(values.get("USER_THEME_BASKETS", {})),
        "sub_theme_baskets": compact(values.get("USER_SUB_THEME_BASKETS", {})),
    }

def compact_yfinance_pack(pack: Any) -> dict[str, Any]:
    if not isinstance(pack, dict):
        return {"available": False, "source": "yfinance_invalid"}
    fundamentals = pack.get("fundamentals") if isinstance(pack.get("fundamentals"), dict) else {}
    keep_fundamentals = [
        "long_name",
        "sector",
        "industry",
        "market_cap",
        "enterprise_value",
        "trailing_pe",
        "forward_pe",
        "price_to_sales",
        "price_to_book",
        "beta",
        "short_percent_float",
        "shares_outstanding",
        "website",
    ]
    holders = pack.get("holders") if isinstance(pack.get("holders"), dict) else {}
    return {
        "available": bool(pack.get("available")),
        "source": pack.get("source") or "yfinance",
        "symbol": pack.get("symbol"),
        "collected_at": pack.get("collected_at"),
        "quote": sanitize(pack.get("quote")),
        "fundamentals": {k: sanitize(fundamentals.get(k), k) for k in keep_fundamentals if k in fundamentals},
        "news": sanitize((pack.get("news") or [])[:5]),
        "calendar": sanitize(pack.get("calendar") or {}),
        "earnings_dates": sanitize((pack.get("earnings_dates") or [])[:5]),
        "recommendations": sanitize((pack.get("recommendations") or [])[:5]),
        "holders": {
            "institutional_holders": sanitize((holders.get("institutional_holders") or [])[:3]) if isinstance(holders, dict) else [],
            "major_holders": sanitize((holders.get("major_holders") or [])[:3]) if isinstance(holders, dict) else [],
        },
        "warnings": sanitize((pack.get("warnings") or [])[:8]),
        "error": sanitize(pack.get("error")),
    }


def compact_toss_pack(pack: Any) -> dict[str, Any]:
    if not isinstance(pack, dict):
        return {"available": False, "source": "toss_wts_invalid"}
    detail = pack.get("detail") if isinstance(pack.get("detail"), dict) else {}
    stock_info = pack.get("stock_info") if isinstance(pack.get("stock_info"), dict) else {}
    consensus = pack.get("consensus") if isinstance(pack.get("consensus"), dict) else {}
    keep_detail = [
        "trade_datetime",
        "price",
        "previous_close",
        "change",
        "pct_change",
        "change_type",
        "open",
        "high",
        "low",
        "volume",
        "previous_volume",
        "volume_vs_previous_pct",
        "trading_value",
        "market_cap",
        "trading_strength",
        "high_52w",
        "low_52w",
        "currency",
        "range_position_pct",
    ]
    keep_info = [
        "name",
        "english_name",
        "market",
        "group",
        "company_name",
        "currency",
        "status",
        "trading_suspended",
        "common_share",
        "spac",
        "shares_outstanding",
        "list_date",
        "daytime_price_supported",
        "option_supported",
        "nxt_supported",
        "isin_code",
    ]
    compact_consensus = {
        "target_mean": consensus.get("target_mean"),
        "target_high": consensus.get("target_high"),
        "target_low": consensus.get("target_low"),
        "target_mean_gap_pct": consensus.get("target_mean_gap_pct"),
        "point_date": consensus.get("point_date"),
        "past_close_prices": sanitize((consensus.get("past_close_prices") or [])[:14]),
    }
    return {
        "available": bool(pack.get("available")),
        "source": pack.get("source") or "toss_wts_insights",
        "symbol": pack.get("symbol"),
        "toss_code": pack.get("toss_code"),
        "collected_at": pack.get("collected_at"),
        "detail": {k: sanitize(detail.get(k), k) for k in keep_detail if k in detail},
        "stock_info": {k: sanitize(stock_info.get(k), k) for k in keep_info if k in stock_info},
        "consensus": compact_consensus,
        "signals": sanitize((pack.get("signals") or [])[:8]),
        "warnings": sanitize((pack.get("warnings") or [])[:8]),
    }


def fetch_terminal_security_pack(symbol: str) -> dict[str, Any]:
    symbol = re.sub(r"[^A-Za-z0-9.=-]", "", symbol.upper().strip())[:12]
    payload: dict[str, Any] = {
        "symbol": symbol,
        "collected_at": utc_now(),
        "sources": [],
        "errors": [],
    }
    if not symbol:
        payload["errors"].append("missing_symbol")
        return payload

    repo_root = Path(__file__).resolve().parents[1]
    src_path = repo_root / "src"
    src_text = str(src_path)
    if src_text not in sys.path:
        sys.path.insert(0, src_text)

    try:
        from us.market_data.yfinance import fetch_toss_wts_insight_packs, fetch_yfinance_market_pack  # type: ignore
    except Exception as exc:  # noqa: BLE001
        payload["errors"].append(f"market_import_failed:{type(exc).__name__}")
        fetch_toss_wts_insight_packs = None  # type: ignore
        fetch_yfinance_market_pack = None  # type: ignore

    try:
        from us.news.sec_filings import fetch_sec_filings_pack  # type: ignore
    except Exception as exc:  # noqa: BLE001
        payload["errors"].append(f"sec_import_failed:{type(exc).__name__}")
        fetch_sec_filings_pack = None  # type: ignore

    if fetch_toss_wts_insight_packs is not None:
        try:
            packs = fetch_toss_wts_insight_packs(
                [symbol],
                include_details=True,
                include_stock_info=True,
                include_consensus=True,
                include_signals=True,
                include_ticks=False,
                include_orderbook=False,
            )
            payload["toss"] = compact_toss_pack(packs.get(symbol))
            payload["sources"].append("toss_wts")
        except Exception as exc:  # noqa: BLE001
            payload["errors"].append(f"toss_wts_failed:{type(exc).__name__}")

    if fetch_sec_filings_pack is not None:
        try:
            payload["sec"] = sanitize(fetch_sec_filings_pack(symbol, limit=8, timeout=12))
            payload["sources"].append("sec_company_submissions")
        except Exception as exc:  # noqa: BLE001
            payload["errors"].append(f"sec_fetch_failed:{type(exc).__name__}")

    if fetch_yfinance_market_pack is not None:
        try:
            payload["yfinance"] = compact_yfinance_pack(fetch_yfinance_market_pack(symbol, max_news=5))
            payload["sources"].append("yfinance_optional")
        except Exception as exc:  # noqa: BLE001
            payload["errors"].append(f"yfinance_failed:{type(exc).__name__}")

    return sanitize(payload)


class DashboardData:
    def __init__(self, hermes_home: Path, job_id: str) -> None:
        self.hermes_home = hermes_home
        self.job_id = job_id
        self.cache_path = hermes_home / CACHE_REL
        self.watchdog_path = hermes_home / WATCHDOG_REL
        self.jobs_path = hermes_home / JOBS_REL
        self.output_dir = hermes_home / "cron" / "output" / job_id
        self.theme_config = load_theme_baskets()
        self.security_cache: dict[str, tuple[float, dict[str, Any]]] = {}
        self.security_cache_ttl_seconds = 600.0
        self.dashboard_cache: dict[int, tuple[float, tuple[tuple[str, int, int], ...], dict[str, Any]]] = {}
        self.dashboard_cache_lock = threading.Lock()
        self.dashboard_cache_ttl_seconds = 60.0

    def latest(self) -> tuple[dict[str, Any], list[str]]:
        errors: list[str] = []
        cache, err = read_json(self.cache_path)
        if err:
            errors.append(err)
        text = ""
        saved_at = None
        source = None
        if isinstance(cache, dict):
            text = str(cache.get("text") or "")
            saved_at = cache.get("saved_at")
            source = cache.get("source")

        if not text:
            latest = self.latest_output_file()
            if latest:
                text, err = read_text(latest)
                if err:
                    errors.append(err)
                text = clean_output_text(text)
                source = f"output:{latest.name}"
                saved_at = datetime.fromtimestamp(latest.stat().st_mtime).isoformat(timespec="seconds")

        return {
            "text": text,
            "sections": parse_sections(text),
            "saved_at": saved_at,
            "source": source,
        }, errors

    def latest_output_file(self) -> Path | None:
        if not self.output_dir.exists():
            return None
        files = [p for p in self.output_dir.glob("*.md") if p.is_file()]
        if not files:
            return None
        return max(files, key=lambda p: p.stat().st_mtime)

    def history(self, limit: int) -> tuple[list[dict[str, Any]], list[str]]:
        errors: list[str] = []
        if not self.output_dir.exists():
            return [], [f"missing: {self.output_dir}"]
        items: list[dict[str, Any]] = []
        files = sorted(
            [p for p in self.output_dir.glob("*.md") if p.is_file()],
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )[:limit]
        for path in files:
            text, err = read_text(path)
            if err:
                errors.append(err)
                text = ""
            stat = path.stat()
            display_time = display_time_from_name(path.stem)
            items.append(
                {
                    "file": path.name,
                    "modified": datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds"),
                    "display_time": display_time,
                    "size": stat.st_size,
                    "size_human": size_human(stat.st_size),
                    "preview": preview_text(text),
                }
            )
        return items, errors

    def status(self) -> tuple[dict[str, Any], list[str]]:
        errors: list[str] = []
        jobs, err = read_json(self.jobs_path)
        if err:
            errors.append(err)
        watchdog, err = read_json(self.watchdog_path)
        if err:
            errors.append(err)

        job = compact_job(find_job(jobs, self.job_id)) if jobs is not None else {}
        watch = compact_watchdog(watchdog)
        latest_file = self.latest_output_file()
        healthy = watch.get("healthy") if isinstance(watch, dict) else None
        if healthy is None and job:
            healthy = job.get("last_status") == "ok" and not job.get("last_delivery_error")

        return {
            "now": utc_now(),
            "hermes_home": str(self.hermes_home),
            "job_id": self.job_id,
            "healthy": healthy,
            "job": job,
            "watchdog_target": watch,
            "latest_output": latest_file.name if latest_file else None,
        }, errors

    def previous_alert(self) -> tuple[dict[str, Any] | None, list[str]]:
        recent, errors = self.recent_alerts(2)
        if len(recent) < 2:
            return None, errors
        return recent[1], errors

    def recent_alerts(self, limit: int = 24) -> tuple[list[dict[str, Any]], list[str]]:
        errors: list[str] = []
        if not self.output_dir.exists():
            return [], []
        files = sorted(
            [p for p in self.output_dir.glob("*.md") if p.is_file()],
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )[: max(1, min(limit, 48))]
        alerts: list[dict[str, Any]] = []
        for path in files:
            text, err = read_text(path)
            if err:
                errors.append(err)
                continue
            text = clean_output_text(text)
            alerts.append(
                {
                    "file": path.name,
                    "text": text,
                    "sections": parse_sections(text),
                    "saved_at": datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds"),
                    "source": f"output:{path.name}",
                }
            )
        return alerts, errors

    def dashboard_signature(self) -> tuple[tuple[str, int, int], ...]:
        signature: list[tuple[str, int, int]] = []
        for path in (self.cache_path, self.watchdog_path, self.jobs_path, self.output_dir):
            try:
                stat = path.stat()
                signature.append((str(path), stat.st_mtime_ns, stat.st_size if path.is_file() else 0))
            except FileNotFoundError:
                signature.append((str(path), 0, 0))
            except OSError:
                signature.append((str(path), -1, 0))
        return tuple(signature)

    def dashboard(self, limit: int) -> dict[str, Any]:
        now = time.monotonic()
        signature = self.dashboard_signature()
        with self.dashboard_cache_lock:
            cached = self.dashboard_cache.get(limit)
            if cached and now - cached[0] < self.dashboard_cache_ttl_seconds and cached[1] == signature:
                return cached[2]

        status, status_errors = self.status()
        latest, latest_errors = self.latest()
        history, history_errors = self.history(limit)
        recent_alerts, recent_errors = self.recent_alerts(24)
        previous_alert = recent_alerts[1] if len(recent_alerts) > 1 else None
        payload = {
            "status": status,
            "latest": latest,
            "previous_alert": previous_alert,
            "recent_alerts": recent_alerts,
            "theme_config": self.theme_config,
            "history": history,
            "errors": status_errors + latest_errors + history_errors + recent_errors,
        }
        with self.dashboard_cache_lock:
            self.dashboard_cache[limit] = (time.monotonic(), signature, payload)
        return payload


    def security(self, symbol: str) -> tuple[dict[str, Any], list[str]]:
        clean_symbol = re.sub(r"[^A-Za-z0-9.=-]", "", str(symbol or "").upper().strip())[:12]
        if not clean_symbol:
            return {"symbol": "", "errors": ["missing_symbol"]}, ["missing_symbol"]
        now_ts = datetime.now(timezone.utc).timestamp()
        cached = self.security_cache.get(clean_symbol)
        if cached and now_ts - cached[0] < self.security_cache_ttl_seconds:
            cached_payload = dict(cached[1])
            cached_payload["cache"] = {"hit": True, "ttl_seconds": self.security_cache_ttl_seconds}
            return cached_payload, []
        payload = fetch_terminal_security_pack(clean_symbol)
        payload["cache"] = {"hit": False, "ttl_seconds": self.security_cache_ttl_seconds}
        self.security_cache[clean_symbol] = (now_ts, payload)
        errors = [str(e) for e in payload.get("errors", [])] if isinstance(payload, dict) else []
        return payload, errors

    def output(self, filename: str) -> tuple[dict[str, Any] | None, str | None]:
        safe_name = Path(filename).name
        if safe_name != filename or not safe_name.endswith(".md"):
            return None, "invalid file name"
        path = self.output_dir / safe_name
        if not path.exists() or not path.is_file():
            return None, f"missing: {safe_name}"
        text, err = read_text(path)
        if err:
            return None, err
        text = clean_output_text(text)
        return {
            "text": text,
            "sections": parse_sections(text),
            "saved_at": datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds"),
            "source": f"output:{path.name}",
        }, None


def make_handler(data: DashboardData):
    class Handler(BaseHTTPRequestHandler):
        server_version = "MarketTerminalDashboard/1.0"

        def send_json(self, payload: Any, status: int = 200) -> None:
            body = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def send_html(self, body: str, status: int = 200) -> None:
            raw = body.encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(raw)))
            self.end_headers()
            self.wfile.write(raw)

        def do_GET(self) -> None:  # noqa: N802 - stdlib API name
            parsed = urlparse(self.path)
            try:
                if parsed.path == "/favicon.ico":
                    self.send_response(204)
                    self.send_header("Cache-Control", "max-age=86400")
                    self.end_headers()
                    return
                if parsed.path in ("/", "/index.html"):
                    self.send_html(INDEX_HTML)
                    return
                if parsed.path == "/api/dashboard":
                    qs = parse_qs(parsed.query)
                    limit = int(qs.get("limit", ["80"])[0])
                    limit = max(1, min(limit, 300))
                    self.send_json(data.dashboard(limit))
                    return
                if parsed.path == "/api/status":
                    status_payload, errors = data.status()
                    self.send_json({"status": status_payload, "errors": errors})
                    return
                if parsed.path == "/api/latest":
                    latest_payload, errors = data.latest()
                    self.send_json({"latest": latest_payload, "errors": errors})
                    return
                if parsed.path == "/api/history":
                    qs = parse_qs(parsed.query)
                    limit = int(qs.get("limit", ["80"])[0])
                    limit = max(1, min(limit, 300))
                    history_payload, errors = data.history(limit)
                    self.send_json({"history": history_payload, "errors": errors})
                    return
                if parsed.path == "/api/security":
                    qs = parse_qs(parsed.query)
                    symbol = qs.get("symbol", [""])[0]
                    payload, errors = data.security(symbol)
                    self.send_json({"security": payload, "errors": errors})
                    return
                if parsed.path == "/api/output":
                    qs = parse_qs(parsed.query)
                    filename = qs.get("file", [""])[0]
                    payload, err = data.output(filename)
                    if err:
                        self.send_json({"error": err}, status=404)
                    else:
                        self.send_json(payload)
                    return
                self.send_json({"error": "not found"}, status=404)
            except Exception as exc:  # noqa: BLE001 - local dashboard should expose failures
                self.send_json({"error": str(exc)}, status=500)

        def log_message(self, fmt: str, *args: Any) -> None:
            sys.stderr.write("[%s] %s\n" % (self.log_date_time_string(), fmt % args))

    return Handler


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="미장 주식 리서치 터미널 웹 UI")
    parser.add_argument("--hermes-home", type=Path, default=DEFAULT_HERMES_HOME, help="Hermes local data directory")
    parser.add_argument("--job-id", default=DEFAULT_JOB_ID, help="Hermes cron job id")
    parser.add_argument("--host", default="127.0.0.1", help="bind host; default is local-only")
    parser.add_argument("--port", type=int, default=8898, help="bind port")
    parser.add_argument("--open", action="store_true", help="open browser after start")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    data = DashboardData(args.hermes_home, args.job_id)
    handler = make_handler(data)
    server = ThreadingHTTPServer((args.host, args.port), handler)
    url = f"http://{args.host}:{args.port}"
    print(f"미장 테마 대시보드 실행 중: {url}")
    print(f"Hermes home: {args.hermes_home}")
    print(f"Job ID: {args.job_id}")
    if args.open:
        threading.Timer(0.5, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n종료합니다.")
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
